<?php $editing=null;foreach($rows as $org){if($org['id']===($_GET['id']??'')){$editing=$org;break;}} ?>
<h1>مجموعه‌ها و جغرافیای تجربه</h1><p class="notice">مجموعه حساب کاربری ندارد. نمایش عمومی فقط پس از تأیید مجموعه و انتشار تجربهٔ دارای انتساب تأییدشده انجام می‌شود. عضویت عملیاتیِ رزرو از این هویت مستقل است.</p>
<div class="row section"><a class="secondary" href="<?= $this->h($this->url('/organizations')) ?>">عضویت‌های عملیاتی رزرو</a><a class="secondary" href="<?= $this->h($this->url('/knowledge')) ?>">روابط و فراداده</a></div>
<section class="card"><h2><?= $editing?'ویرایش مجموعه':'ثبت مجموعه' ?></h2><?= $this->start('/atlas/organization/save') ?><input type="hidden" name="id" value="<?= $this->h($editing['id']??'') ?>"><?= $this->field('name','نام مجموعه','text',$editing['name']??'') ?><label>نوع مجموعه<select name="org_type"><?php foreach(['heyat'=>'هیئت','charity'=>'خیریه','cultural'=>'فرهنگی','business'=>'کسب‌وکار','other'=>'سایر'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($editing['org_type']??'other')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>معرفی<textarea name="description" maxlength="6000"><?= $this->h($editing['description']??'') ?></textarea></label><div class="grid2"><?php $placePrefix='org';$selectedProvince=$editing['province_id']??'';$selectedCounty=$editing['county_id']??'';require __DIR__.'/atlas-place-fields.php'; ?></div><label>نام‌های دیگر، هر نام در یک خط<textarea name="aliases" maxlength="1600"><?= $this->h(implode("\n",array_column(array_filter($aliases,fn($a)=>$a['org_id']===($editing['id']??'')),'alias'))) ?></textarea></label><label>وضعیت<select name="active"><option value="1">فعال</option><option value="0" <?= isset($editing['active'])&&!$editing['active']?'selected':'' ?>>غیرفعال</option></select></label><label class="check"><input type="checkbox" name="verified" value="1" <?= !empty($editing['verified_at'])?'checked':'' ?>>هویت و محل مجموعه بررسی و تأیید شد</label><button>ذخیرهٔ مجموعه</button></form></section>
<section class="card section"><h2>مجموعه‌های ثبت‌شده</h2><div class="table-scroll"><table><thead><tr><th>نام</th><th>مکان</th><th>تأیید</th><th>ویرایش</th></tr></thead><tbody><?php foreach($rows as $o): ?><tr><td><?= $this->h($o['name']) ?><?= $o['merged_into']?' · ادغام‌شده':'' ?></td><td><?= $this->h(($o['province_name']??'نامشخص').' / '.($o['county_name']??'نامشخص')) ?></td><td><?= $o['verified_at']?'تأییدشده':'بررسی نشده' ?></td><td><?php if(!$o['merged_into']): ?><a href="<?= $this->h($this->url('/atlas/manage?id='.$o['id'])) ?>">ویرایش اطلاعات</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card section"><h2>انتساب مجموعه یا مکان به نسخهٔ تجربه</h2><p class="muted">انتساب هر نسخه مستقل است؛ تغییر نسخهٔ پیش‌نویس، نسخهٔ عمومی را تغییر نمی‌دهد. رد یا لغو تأیید در تاریخچه ثبت می‌شود.</p><?= $this->start('/atlas/attribution') ?><label>نسخهٔ تجربه<select name="version_id" required><?php foreach($versions as $v): ?><option value="<?= $this->h($v['id']) ?>"><?= $this->h($v['title']) ?> · نسخه <?= (int)$v['version_no'] ?> · <?= $this->status($v['status']) ?></option><?php endforeach; ?></select></label><label>نوع انتساب<select name="kind"><option value="organization">مجموعه</option><option value="place">مکان تجربه</option></select></label><label>مجموعه<select name="org_id"><option value="">انتخاب مجموعه</option><?php foreach($rows as $o):if(!$o['active']||$o['merged_into']){continue;} ?><option value="<?= $this->h($o['id']) ?>"><?= $this->h($o['name']) ?></option><?php endforeach; ?></select></label><label>نوع ارتباط<select name="relation_type"><option value="formed_at">تجربه در مجموعه شکل گرفته</option><option value="co_implementer">همکاری در اجرا</option><option value="other">سایر، با توضیح مدرک</option></select></label><div class="grid2"><?php $placePrefix='experience';$selectedProvince='';$selectedCounty='';require __DIR__.'/atlas-place-fields.php'; ?></div><label>نوع مکان<select name="location_type"><option value="execution">محل اجرا</option><option value="formation">محل شکل‌گیری</option></select></label><?= $this->field('raw_name','نام اولیهٔ مجموعه (خصوصی)','text','',false,180) ?><?= $this->field('evidence','ارجاع مدرک بررسی (خصوصی)','text','',false,500) ?><label>یادداشت خصوصی<textarea name="internal_note" maxlength="3000"></textarea></label><label>تصمیم<select name="status"><option value="proposed">در انتظار بررسی</option><option value="approved">تأییدشده</option><option value="rejected">ردشده</option><option value="revoked">لغو تأیید</option></select></label><label class="check"><input type="checkbox" name="is_primary" value="1">انتساب اصلی این نسخه</label><button>ثبت و نگهداری تصمیم در تاریخچه</button></form></section>
<section class="card section"><h2>صف بررسی انتساب‌ها</h2><?php foreach($queue as $item): ?><p><?= $this->h($item['title'].' ← '.$item['name']) ?> · <code><?= $this->h($item['version_id']) ?></code></p><?php endforeach; ?><?php if(!$queue): ?><p class="muted">انتساب بررسی‌نشده‌ای نداریم.</p><?php endif; ?><h3>تجربه‌های عمومی بدون مکان تأییدشده</h3><?php foreach($missing as $v): ?><p><?= $this->h($v['title']) ?> · <code><?= $this->h($v['version_id']) ?></code></p><?php endforeach; ?></section>
<details class="card section"><summary>ادغام دو مجموعهٔ تکراری</summary><p>هویت مبدأ به مقصد ارجاع داده می‌شود؛ سوابق انتساب و عضویت‌های عملیاتی حذف نمی‌شوند. نام مشترک به‌تنهایی دلیل ادغام نیست.</p><?= $this->start('/atlas/organization/merge') ?><?php foreach(['from'=>'مبدأ تکراری','into'=>'مقصد معتبر'] as $key=>$label): ?><label><?= $label ?><select name="<?= $key ?>"><?php foreach($rows as $o):if($o['merged_into']){continue;} ?><option value="<?= $this->h($o['id']) ?>"><?= $this->h($o['name'].' · '.($o['county_name']??'مکان نامشخص')) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><button>ادغام با حفظ سابقه</button></form></details>
